CREATE TABLE advance_bookings(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`listing_id` BIGINT  NOT NULL,`buyer_id` BIGINT  NOT NULL,`farmer_id` BIGINT  NOT NULL,`quantity_booked` DECIMAL(10,2)  NOT NULL,`price_per_unit` DECIMAL(10,2)  NOT NULL,`total_amount` DECIMAL(10,2)  NOT NULL,`advance_payment_percent` INT  NOT NULL DEFAULT 20,`advance_payment_amount` DECIMAL(10,2)  NOT NULL,`booking_date` timestamp  NOT NULL DEFAULT CURRENT_TIMESTAMP,`expected_delivery_date` timestamp  NOT NULL,`status` varchar(50)  NOT NULL DEFAULT 'pending',`quality_standards` text  NULL,`contract_terms` text  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;